const out = [];
for (const item of $input.all()) {
  const update = item.json;
  const msg = update.message || update.channel_post || update.edited_message || update.edited_channel_post;
  if (!msg || !msg.text) continue;
  const chatId = String(msg.chat?.id ?? '');
  const messageId = String(msg.message_id ?? '');
  const sender = msg.from?.username || msg.from?.first_name || null;
  const text = msg.text || '';
  const receivedAt = new Date((msg.date ? msg.date * 1000 : Date.now())).toISOString();
  out.push({
    json: {
      channel: 'telegram',
      external_chat_id: chatId,
      external_message_id: messageId,
      sender,
      raw_text: text,
      raw_payload: update,
      received_at: receivedAt,
      is_test: false
    }
  });
}
return out;

const out = [];
for (const item of $input.all()) {
  const body = item.json;
  const entries = body.entry || [];
  for (const entry of entries) {
    const changes = entry.changes || [];
    for (const change of changes) {
      const value = change.value || {};
      const messages = value.messages || [];
      for (const m of messages) {
        const chatId = String(value.metadata?.phone_number_id ?? m.from ?? '');
        const messageId = String(m.id ?? '');
        const text = m.text?.body || m.button?.text || '';
        if (!text) continue;
        const receivedAt = new Date((m.timestamp ? Number(m.timestamp) * 1000 : Date.now())).toISOString();
        out.push({
          json: {
            channel: 'whatsapp',
            external_chat_id: chatId,
            external_message_id: messageId,
            sender: m.from || null,
            raw_text: text,
            raw_payload: body,
            received_at: receivedAt,
            is_test: false
          }
        });
      }
    }
  }
}
return out;

// WAITING FOR OFFICIAL SMC API ACCESS — upstream HTTP node is disabled.
// The response shape below is a placeholder guess, not a documented
// contract. Update once real API docs exist; keep the HTTP node disabled
// until then.
const out = [];
for (const item of $input.all()) {
  const rows = Array.isArray(item.json) ? item.json : (item.json.data || item.json.signals || []);
  for (const row of rows) {
    const text = row.text || row.message || JSON.stringify(row);
    out.push({
      json: {
        channel: 'api',
        external_chat_id: 'smc_auto_trender',
        external_message_id: String(row.id ?? ''),
        sender: 'smc_auto_trender',
        raw_text: text,
        raw_payload: row,
        received_at: new Date().toISOString(),
        is_test: false
      }
    });
  }
}
return out;

// Deterministic sample so the full pipeline can be exercised without
// touching a real source or a real client-facing channel. "Test Mode
// Check" downstream skips the real Telegram/WhatsApp sends for is_test
// items.
//
// Before running: register a signal_sources row for this fixture, e.g.
//   insert into signal_sources (slug, name, kind, telegram_chat_id, is_active)
//   values ('test-fixture', 'Test Fixture', 'manual', 'TEST_FIXTURE', true);
const text = 'BUY BANKNIFTY 51000 CE above 420, SL 380, Target1 460 Target2 500. Intraday view, 30-45 min timeframe.';
const id = `test-${Date.now()}`;
return [{
  json: {
    channel: 'telegram',
    external_chat_id: 'TEST_FIXTURE',
    external_message_id: id,
    sender: 'test_harness',
    raw_text: text,
    raw_payload: { source: 'test_mode_trigger' },
    received_at: new Date().toISOString(),
    is_test: true
  }
}];

const VALID_CATEGORIES = ['F&O','EQUITY','COMMODITY','IPO','SIP','MUTUAL_FUND','INVESTMENT','INSURANCE','LOAN','MARKET_UPDATE','EDUCATION','OTHER'];
const TRADE_CATEGORIES = ['F&O','EQUITY','COMMODITY'];
const num = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const asObj = (raw, label, errors) => {
  if (raw === null || raw === undefined) { errors.push(`${label} produced no output.`); return {}; }
  if (typeof raw === 'object') return raw;
  try { return JSON.parse(raw); }
  catch (e) { errors.push(`${label} output was not valid JSON: ${e.message}`); return {}; }
};

const out = [];
for (const item of $input.all()) {
  const rm = $('Insert Raw Message').item.json;
  const isTest = $('Merge All Sources').item.json.is_test === true;
  const parseErrors = [];

  const mark = asObj($('MARK - Market Analyst').item.json.output, 'MARK', parseErrors);
  const muse = asObj($('MUSE - Strategy Analyst').item.json.output, 'MUSE', parseErrors);
  const echo = asObj($('ECHO - Signal Validator').item.json.output, 'ECHO', parseErrors);
  const scout = asObj($('SCOUT - Intelligence Agent').item.json.output, 'SCOUT', parseErrors);
  const atlas = asObj($('ATLAS - Final Verdict Coordinator').item.json.output, 'ATLAS', parseErrors);

  const category = VALID_CATEGORIES.includes(atlas.category) ? atlas.category : (VALID_CATEGORIES.includes(mark.category) ? mark.category : 'OTHER');
  const isTradeCategory = TRADE_CATEGORIES.includes(category);
  const action = (mark.action === 'BUY' || mark.action === 'SELL') ? mark.action : null;
  const targets = Array.isArray(mark.targets) ? mark.targets.map(num).filter((v) => v !== null) : [];
  const entry = num(mark.entry);
  const stopLoss = num(mark.stop_loss);
  const confidence = num(atlas.confidence);
  const isSignal = mark.is_signal === true && atlas.is_signal !== false;
  const echoStatus = ['passed', 'flagged', 'rejected'].includes(echo.validation_status) ? echo.validation_status : null;
  const validationFlags = Array.isArray(echo.validation_flags) ? echo.validation_flags : [];

  let validationReason = null;
  if (parseErrors.length) validationReason = parseErrors.join(' ');
  else if (!isSignal) validationReason = 'Agents classified this as not a signal.';
  else if (echoStatus === 'rejected') validationReason = echo.reject_reason || 'ECHO rejected this signal during validation.';
  else if (atlas.processing_status === 'quarantine_recommended') validationReason = atlas.final_verdict || 'ATLAS recommended quarantine.';
  else if (isTradeCategory && !mark.symbol) validationReason = 'No symbol/instrument identified.';
  else if (isTradeCategory && !action) validationReason = 'Trade category but no clear BUY/SELL action.';
  else if (entry !== null && stopLoss !== null && entry === stopLoss) validationReason = 'Entry and stop-loss are identical.';
  else if (confidence !== null && (confidence < 0 || confidence > 100)) validationReason = 'Confidence out of range.';
  const valid = validationReason === null;

  const today = new Date().toISOString().slice(0, 10);
  const fingerprintSource = [category, mark.symbol, action, entry, stopLoss, targets.join(',')]
    .map((v) => (v === null || v === undefined) ? '' : String(v))
    .join('|')
    .toUpperCase();
  const fingerprint = `${today}|${fingerprintSource}`;

  out.push({
    json: {
      valid,
      validation_reason: validationReason,
      category,
      is_trade_category: isTradeCategory,
      instrument: mark.instrument ?? null,
      symbol: mark.symbol ?? null,
      exchange: mark.exchange ?? null,
      action,
      entry,
      stop_loss: stopLoss,
      target_1: targets[0] ?? null,
      target_2: targets[1] ?? null,
      target_3: targets[2] ?? null,
      expiry: mark.expiry ?? null,
      timeframe: mark.timeframe ?? null,
      confidence,
      rationale: atlas.final_verdict ?? null,
      risk_note: atlas.risk_notes ?? null,
      market_context: mark.market_context ?? null,
      validation_status: echoStatus,
      validation_flags: validationFlags,
      agent_outputs: { mark, muse, echo, scout, atlas },
      raw_message: rm.raw_text,
      normalized_message: atlas.normalized_message ?? rm.raw_text,
      fingerprint,
      raw_message_id: rm.id,
      source_id: rm.source_id,
      channel: rm.channel,
      source_message_id: rm.external_message_id,
      source_timestamp: rm.received_at,
      is_test: isTest
    }
  });
}
return out;
